def test_authentication_router(
    client: TestClient,
    accounts: dict[str, int | str],
) -> None:
    token = login(
        client,
        str(accounts["customer_email"]),
        str(accounts["customer_password"]),
    )

    assert token

    invalid_response = client.post(
        "/api/auth/login",
        data={
            "username": str(accounts["customer_email"]),
            "password": "WrongPassword123",
        },
    )

    assert invalid_response.status_code == 401


def test_user_router(
    client: TestClient,
    accounts: dict[str, int | str],
) -> None:
    token = login(
        client,
        str(accounts["customer_email"]),
        str(accounts["customer_password"]),
    )

    response = client.get(
        f"/api/users/{accounts['customer_id']}",
        headers=auth_headers(token),
    )

    assert response.status_code == 200

    user_data = response.json()

    assert user_data["user_id"] == accounts["customer_id"]
    assert user_data["email"] == CUSTOMER_EMAIL
    assert "password" not in user_data
    assert "Password" not in user_data


def test_category_router(
    client: TestClient,
    catalog: dict[str, int],
) -> None:
    response = client.get("/api/categories")

    assert response.status_code == 200

    categories = response.json()

    assert len(categories) == 1
    assert categories[0]["category_id"] == catalog["category_id"]
    assert categories[0]["category_name"] == "Electronics"


def test_product_router(
    client: TestClient,
    catalog: dict[str, int],
) -> None:
    list_response = client.get("/api/products")

    assert list_response.status_code == 200
    assert len(list_response.json()) == 1

    search_response = client.get(
        "/api/products/search",
        params={"name": "laptop"},
    )

    assert search_response.status_code == 200
    assert len(search_response.json()) == 1
    assert search_response.json()[0]["product_name"] == "Test Laptop"

    detail_response = client.get(
        f"/api/products/{catalog['product_id']}",
    )

    assert detail_response.status_code == 200
    assert detail_response.json()["product_id"] == (
        catalog["product_id"]
    )

    not_found_response = client.get("/api/products/99999")

    assert not_found_response.status_code == 404

