def test_admin_router(
    client: TestClient,
    accounts: dict[str, int | str],
    catalog: dict[str, int],
) -> None:
    admin_token = login(
        client,
        str(accounts["admin_email"]),
        str(accounts["admin_password"]),
    )

    admin_headers = auth_headers(admin_token)

    update_product_response = client.put(
        f"/api/admin/products/{catalog['product_id']}",
        headers=admin_headers,
        json={
            "price": "799.99",
            "available_quantity": 25,
        },
    )

    assert update_product_response.status_code == 200, (
        update_product_response.text
    )

    assert Decimal(
        str(update_product_response.json()["price"]),
    ) == Decimal("799.99")

    update_category_response = client.put(
        f"/api/admin/categories/{catalog['category_id']}",
        headers=admin_headers,
        json={
            "category_name": "Updated Electronics",
        },
    )

    assert update_category_response.status_code == 200, (
        update_category_response.text
    )

    orders_response = client.get(
        "/api/admin/orders",
        headers=admin_headers,
    )

    assert orders_response.status_code == 200
    assert isinstance(orders_response.json(), list)


def test_customer_cannot_access_admin_router(
    client: TestClient,
    accounts: dict[str, int | str],
    catalog: dict[str, int],
) -> None:
    customer_token = login(
        client,
        str(accounts["customer_email"]),
        str(accounts["customer_password"]),
    )

    customer_headers = auth_headers(customer_token)

    product_response = client.post(
        "/api/admin/products",
        headers=customer_headers,
        json={
            "product_name": "Unauthorized Product",
            "description": "Should be rejected",
            "category_id": catalog["category_id"],
            "price": "10.00",
            "available_quantity": 5,
        },
    )

    assert product_response.status_code == 403

    category_response = client.post(
        "/api/admin/categories",
        headers=customer_headers,
        json={
            "category_name": "Unauthorized Category",
        },
    )

    assert category_response.status_code == 403

    orders_response = client.get(
        "/api/admin/orders",
        headers=customer_headers,
    )

    assert orders_response.status_code == 403


